#include <pthread.h>
#include <stdio.h>

#define N 10000000
static volatile int counter = 0;

static void *worker(void *arg) {
    for (int i = 0; i < N; i++)
        counter = counter + 1;   /* 보호 없는 임계 구역 */
    return NULL;
}

int main(void) {
    pthread_t a, b;
    pthread_create(&a, NULL, worker, NULL);
    pthread_create(&b, NULL, worker, NULL);
    pthread_join(a, NULL);
    pthread_join(b, NULL);
    printf("counter = %d (expected %d)\n", counter, 2 * N);
    return 0;
}
// 6코어 WSL 실행 결과: 11952084, 12173106, 12214238 (기대값 20000000)

int flag[2] = {0, 0};
int turn;

void lock(int self) {
    flag[self] = 1;          /* 나도 들어가고 싶다 */
    turn = 1 - self;         /* 상대에게 먼저 양보 */
    /* 현대 CPU에서는 여기에 atomic_thread_fence(memory_order_seq_cst) 필요 */
    while (flag[1 - self] && turn == 1 - self)
        ;                    /* 바쁜 대기 */
}

void unlock(int self) { flag[self] = 0; }
// x86-64, 1000만 번: 배리어 없음 9999694 · 9999850 · 9999949 / 배리어 있음 10000000 x3

#include <stdatomic.h>

atomic_flag lock = ATOMIC_FLAG_INIT;

void acquire(void) {
    while (atomic_flag_test_and_set(&lock))   /* x86-64: xchg */
        ;                                      /* spin */
}

void release(void) {
    atomic_flag_clear(&lock);
}
